import{bV as e,aL as l,u as a,G as n}from"./chunks/framework.DW3NRN-T.js";const y=JSON.parse('{"title":"吴师兄学大模型_公众号文章问题解答汇总","description":"","frontmatter":{"title":"吴师兄学大模型_公众号文章问题解答汇总","permalink":"/aigc/interview/wuxiong-summary","tags":["面试题","吴师兄","大模型"],"categories":["面试题"]},"headers":[],"relativePath":"AIGC/AI应用开发/06.AI面试题/8_吴师兄学大模型_公众号文章问题解答汇总.md","filePath":"AIGC/AI应用开发/06.AI面试题/8_吴师兄学大模型_公众号文章问题解答汇总.md","lastUpdated":1782121451000}'),d={name:"AIGC/AI应用开发/06.AI面试题/8_吴师兄学大模型_公众号文章问题解答汇总.md"};function r(i,t,s,g,o,x){return l(),a("div",null,[...t[0]||(t[0]=[n('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /AIGC/AI应用开发/06.AI面试题/8_吴师兄学大模型_公众号文章问题解答汇总.md for this page in Markdown format</div><h1 id="微信公众号「吴师兄学大模型」文章问题与解答汇总" tabindex="-1">微信公众号「吴师兄学大模型」文章问题与解答汇总 <a class="header-anchor" href="#微信公众号「吴师兄学大模型」文章问题与解答汇总" aria-label="Permalink to &quot;微信公众号「吴师兄学大模型」文章问题与解答汇总&quot;">​</a></h1><blockquote><p>整理时间：2026-06-16<br> 数据来源：微信公众号、吴师兄大模型面试题网站(wushixiongai.com)、知乎专栏、今天看啥(jintiankansha.com)、搜狐/CSDN转载<br> 说明：公众号主体包含「吴师兄学大模型」和「吴师兄学算法」两个矩阵号</p></blockquote><hr><h2 id="一、公众号概况" tabindex="-1">一、公众号概况 <a class="header-anchor" href="#一、公众号概况" aria-label="Permalink to &quot;一、公众号概况&quot;">​</a></h2><p>吴师兄（程序员吴师兄）运营的公众号矩阵，专注于大模型/LLM工程师面试题解答，涵盖以下方向：</p><table tabindex="0"><thead><tr><th style="text-align:left;">方向</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>RAG（检索增强生成）</strong></td><td style="text-align:left;">20+篇系列文章，覆盖检索、分块(chunk)、Embedding、Rerank、幻觉、评估、性能优化</td></tr><tr><td style="text-align:left;"><strong>Agent（智能体）</strong></td><td style="text-align:left;">工具调用、长期记忆、ReAct框架、LLM vs Agent 区别</td></tr><tr><td style="text-align:left;"><strong>模型架构</strong></td><td style="text-align:left;">Flash Attention、LayerNorm/RMSNorm、位置编码、Prefix LM vs Causal LM</td></tr><tr><td style="text-align:left;"><strong>模型训练</strong></td><td style="text-align:left;">DDPM、Flow Matching、SFT、PyTorch动态计算图</td></tr><tr><td style="text-align:left;"><strong>强化学习与对齐</strong></td><td style="text-align:left;">PPO/DPO/GRPO、Reward函数设计、RLHF、长周期任务</td></tr><tr><td style="text-align:left;"><strong>推理优化与部署</strong></td><td style="text-align:left;">vLLM/TensorRT-LLM/TGI/llama.cpp对比、模型量化、Continuous Batching</td></tr><tr><td style="text-align:left;"><strong>工程实践</strong></td><td style="text-align:left;">复杂文档解析(PDF/表格)、面试表达、项目排查</td></tr></tbody></table><p>面试题库共计 <strong>840道</strong> 真题，每道都有书面答案 + 口语版讲法 + 概念图解。</p><hr><h2 id="二、文章分类及问题列表" tabindex="-1">二、文章分类及问题列表 <a class="header-anchor" href="#二、文章分类及问题列表" aria-label="Permalink to &quot;二、文章分类及问题列表&quot;">​</a></h2><h3 id="_2-1-rag-检索增强生成-系列-20-篇" tabindex="-1">2.1 RAG（检索增强生成）系列（20+篇） <a class="header-anchor" href="#_2-1-rag-检索增强生成-系列-20-篇" aria-label="Permalink to &quot;2.1 RAG（检索增强生成）系列（20+篇）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">序号</th><th style="text-align:left;">文章标题</th><th style="text-align:left;">核心问题</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">滴滴面试官：&quot;你做RAG，是真的需要，还是你根本没算过成本？&quot;</td><td style="text-align:left;">如何判断业务是否真正需要RAG？如何评估RAG的投入产出比？</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">腾讯大模型二面：RAG系统做完了，向量数据库怎么选、Embedding怎么选、chunk大小怎么选？</td><td style="text-align:left;">RAG技术选型三要素：向量数据库、Embedding模型、分块大小</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">阿里大模型二面：Embedding模型怎么选？Rerank为什么不直接用GPT-4？</td><td style="text-align:left;">Embedding模型选型标准；为何Rerank用轻量模型而非GPT-4？</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">阿里大模型三面：RAG的chunk用固定512切分，召回率67%，面试官追问三个为什么</td><td style="text-align:left;">固定chunk策略为何召回率低？如何优化分块策略？</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">京东面试官连环问：&quot;你RAG召回了20条，有15条是垃圾，Rerank怎么做的？&quot;</td><td style="text-align:left;">初步检索结果质量差时，如何通过Rerank提升上下文质量？</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">京东面试官问：&quot;你的RAG系统检索结果很准，但最终答案还是有幻觉，Prompt怎么写的？&quot;</td><td style="text-align:left;">检索准确但生成仍有幻觉时，如何优化Prompt（System Prompt）？</td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;">淘天大模型三面：RAG生成答案不准，你如何定位和解决幻觉问题？</td><td style="text-align:left;">RAG幻觉的系统定位方法：检索问题→Prompt问题→生成模型问题</td></tr><tr><td style="text-align:left;">8</td><td style="text-align:left;">蚂蚁大模型三面：RAG系统怎么评估？测试集构建、检索指标、生成指标全拆解</td><td style="text-align:left;">RAG系统评估体系：测试集构建、检索指标(Recall/NDCG)、生成指标(Faithfulness/Relevance)</td></tr><tr><td style="text-align:left;">9</td><td style="text-align:left;">京东大模型二面：你的RAG系统首字响应要5秒，怎么优化？</td><td style="text-align:left;">RAG系统延迟优化：检索、重排、生成各环节的优化策略</td></tr><tr><td style="text-align:left;">10</td><td style="text-align:left;">字节大模型二面：PDF表格解析准确率只有32%，你们的RAG系统怎么保证答案质量？</td><td style="text-align:left;">复杂格式文档解析准确率低时，如何保证RAG输出质量？</td></tr><tr><td style="text-align:left;">11</td><td style="text-align:left;">阿里大模型二面：PDF、表格、图片混排文档，你的RAG系统是怎么解析的？</td><td style="text-align:left;">混合格式文档（文字+表格+图片）的RAG解析流程</td></tr><tr><td style="text-align:left;">12</td><td style="text-align:left;">京东面试官：&quot;检索到了正确的文档，大模型还是在胡说&quot;</td><td style="text-align:left;">RAG生成阶段核心问题：明明检索正确为何仍出错？(检索增强与生成脱节问题)</td></tr><tr><td style="text-align:left;">13</td><td style="text-align:left;">面试官问：为什么你的RAG能做得比别人好？</td><td style="text-align:left;">方法论总结：讲思考而非背答案、解释取舍而非列概念、讲落地逻辑而非堆理论</td></tr></tbody></table><h3 id="_2-2-agent-智能体-系列" tabindex="-1">2.2 Agent（智能体）系列 <a class="header-anchor" href="#_2-2-agent-智能体-系列" aria-label="Permalink to &quot;2.2 Agent（智能体）系列&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">序号</th><th style="text-align:left;">文章标题</th><th style="text-align:left;">核心问题</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">阿里一面：LLM和Agent有什么区别？Agent到底多了什么？</td><td style="text-align:left;">LLM vs Agent的本质区别：规划、记忆、工具使用等额外能力</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">美团二面：Agent的工具调用和普通函数调用有什么区别？</td><td style="text-align:left;">Agent工具调用(Function Call)与传统函数调用的本质差异</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">字节一面：说说ReAct框架，Thought-Action-Observation各是什么？</td><td style="text-align:left;">ReAct框架的三组件详解：思考→行动→观察</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">面试官追问：&quot;你的Agent说有长期记忆，用户上周问的问题这周还记得，这个记忆存在哪？怎么检索？&quot;</td><td style="text-align:left;">Agent长期记忆的存储方案与检索策略</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">鹅厂面试官皱眉：&quot;你用Claude Code这么久，它怎么记住你偏好的？&quot;</td><td style="text-align:left;">AI编程助手的长期记忆机制（对话历史、上下文工程）</td></tr></tbody></table><h3 id="_2-3-模型架构-architecture" tabindex="-1">2.3 模型架构（Architecture） <a class="header-anchor" href="#_2-3-模型架构-architecture" aria-label="Permalink to &quot;2.3 模型架构（Architecture）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">序号</th><th style="text-align:left;">面试题</th><th style="text-align:left;">分类</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;"><strong>快手一面：Prefix LM和Causal LM到底差在哪？</strong></td><td style="text-align:left;">架构对比</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">请解释Flash Attention的算法设计原理，它是如何通过融合计算与I/O优化来提升Transformer注意力机制效率的？</td><td style="text-align:left;">注意力优化</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">在大模型架构中，为何Transformer系列普遍采用Layer Normalization而非Batch Normalization？</td><td style="text-align:left;">归一化选型</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">在大模型的实际应用中，Layer Normalization和RMS Normalization有哪些主要区别？主流模型更倾向于使用哪种？</td><td style="text-align:left;">归一化对比</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">在Transformer模型中，为何选择Layer Normalization而非Batch Normalization？（变体）</td><td style="text-align:left;">归一化选型</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">在现代大模型架构中，LayerNorm与RMSNorm在计算方式、数值稳定性、训练动态和内存效率方面有何主要区别？（变体）</td><td style="text-align:left;">归一化对比</td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;">在Transformer模型中为何要引入归一化层？请说明其作用机制</td><td style="text-align:left;">归一化原理</td></tr><tr><td style="text-align:left;">8</td><td style="text-align:left;">请解释位置编码在Transformer模型中的作用，并说明为什么它对模型性能至关重要</td><td style="text-align:left;">位置编码</td></tr><tr><td style="text-align:left;">9</td><td style="text-align:left;">请简要说明当前大规模语言模型在实际应用和研究中面临的主要挑战和技术瓶颈</td><td style="text-align:left;">LLM挑战</td></tr></tbody></table><h3 id="_2-4-模型训练-training" tabindex="-1">2.4 模型训练（Training） <a class="header-anchor" href="#_2-4-模型训练-training" aria-label="Permalink to &quot;2.4 模型训练（Training）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">序号</th><th style="text-align:left;">面试题</th><th style="text-align:left;">分类</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">请比较DDPM与Flow Matching在建模思路、训练目标、采样效率和理论基础方面的核心区别</td><td style="text-align:left;">生成模型</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">在DDPM的训练过程中，为何采用随机选择时间步进行加噪并学习对应去噪的方式？</td><td style="text-align:left;">训练策略</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">在进行监督微调（SFT）后，某些分类模型的预测概率分布从原本较为集中变为更加均匀，请分析原因</td><td style="text-align:left;">SFT现象</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">请解释PyTorch中动态计算图的工作机制，包括自动微分的实现原理</td><td style="text-align:left;">框架原理</td></tr></tbody></table><h3 id="_2-5-强化学习与对齐-rl-alignment" tabindex="-1">2.5 强化学习与对齐（RL &amp; Alignment） <a class="header-anchor" href="#_2-5-强化学习与对齐-rl-alignment" aria-label="Permalink to &quot;2.5 强化学习与对齐（RL &amp; Alignment）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">序号</th><th style="text-align:left;">面试题</th><th style="text-align:left;">分类</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">请详细说明PPO、DPO和GRPO三种优化算法的核心思想、适用场景及主要区别</td><td style="text-align:left;">算法对比</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">请比较DPO与PPO在大模型对齐中的应用，从算法原理、实现复杂度、训练稳定性和效果表现等方面进行分析</td><td style="text-align:left;">对齐方法</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">在RLHF中，设计Reward函数时应综合考虑哪些关键因素？</td><td style="text-align:left;">Reward设计</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">在强化学习或Agent系统中，如何设计一个有效的奖励函数？</td><td style="text-align:left;">Reward设计</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">在基于强化学习的Agent训练中，奖励函数的设计至关重要，请说明设计原则</td><td style="text-align:left;">Reward设计</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">在强化学习或Agent系统中，如何对长周期（long-horizon）任务进行建模和训练？</td><td style="text-align:left;">长周期任务</td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;">在处理长视野任务时，智能体常面临稀疏奖励和信用分配难题，请说明关键技术手段</td><td style="text-align:left;">稀疏奖励</td></tr><tr><td style="text-align:left;">8</td><td style="text-align:left;">长视界任务因奖励稀疏和信用分配困难而极具挑战性，请说明训练策略</td><td style="text-align:left;">长视界任务</td></tr></tbody></table><h3 id="_2-6-推理优化与部署-inference-deployment" tabindex="-1">2.6 推理优化与部署（Inference &amp; Deployment） <a class="header-anchor" href="#_2-6-推理优化与部署-inference-deployment" aria-label="Permalink to &quot;2.6 推理优化与部署（Inference &amp; Deployment）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">序号</th><th style="text-align:left;">面试题</th><th style="text-align:left;">分类</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">在大模型应用中，常见的模型优化方法有哪些？请从训练、推理和部署角度阐述</td><td style="text-align:left;">全局优化</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">请列举并比较主流的大语言模型推理框架（vLLM、TensorRT-LLM、HuggingFace TGI、llama.cpp等）</td><td style="text-align:left;">推理框架</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">当一个大模型在特定任务或任务类别上表现不佳时，有哪些系统性的排查和优化策略？</td><td style="text-align:left;">问题排查</td></tr></tbody></table><hr><h2 id="三、核心问题详细解答" tabindex="-1">三、核心问题详细解答 <a class="header-anchor" href="#三、核心问题详细解答" aria-label="Permalink to &quot;三、核心问题详细解答&quot;">​</a></h2><h3 id="_3-1-prefix-lm-vs-causal-lm" tabindex="-1">3.1 Prefix LM vs Causal LM <a class="header-anchor" href="#_3-1-prefix-lm-vs-causal-lm" aria-label="Permalink to &quot;3.1 Prefix LM vs Causal LM&quot;">​</a></h3><blockquote><p>来源：快手一面面试题</p></blockquote><p><strong>核心区别</strong>：对上下文信息的利用方式不同。</p><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">Causal LM（因果语言模型）</th><th style="text-align:left;">Prefix LM（前缀语言模型）</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>建模逻辑</strong></td><td style="text-align:left;">单向建模，每个token仅依赖左侧已出现的token</td><td style="text-align:left;">分段建模：前缀段双向依赖 + 预测段单向自回归</td></tr><tr><td style="text-align:left;"><strong>注意力机制</strong></td><td style="text-align:left;">下三角注意力掩码，完全屏蔽右侧信息</td><td style="text-align:left;">混合注意力掩码：前缀段内双向，预测段内单向</td></tr><tr><td style="text-align:left;"><strong>典型模型</strong></td><td style="text-align:left;">GPT系列、LLaMA</td><td style="text-align:left;">T5、UL2(Prefix LM模式)、PEGASUS</td></tr><tr><td style="text-align:left;"><strong>适用场景</strong></td><td style="text-align:left;">纯生成任务：对话、续写、代码生成</td><td style="text-align:left;">条件生成任务：摘要、翻译、问答</td></tr><tr><td style="text-align:left;"><strong>优点</strong></td><td style="text-align:left;">工程实现简单，生成速度快</td><td style="text-align:left;">兼顾理解与生成，灵活性更强</td></tr><tr><td style="text-align:left;"><strong>缺点</strong></td><td style="text-align:left;">上下文理解受限</td><td style="text-align:left;">模型结构复杂，推理速度稍慢</td></tr></tbody></table><p><strong>关键认知</strong>：Prefix LM允许上下文样本之间进行全局注意力（双向），在In-Context Learning任务中可能优于Causal LM。</p><h3 id="_3-2-flash-attention算法设计原理" tabindex="-1">3.2 Flash Attention算法设计原理 <a class="header-anchor" href="#_3-2-flash-attention算法设计原理" aria-label="Permalink to &quot;3.2 Flash Attention算法设计原理&quot;">​</a></h3><blockquote><p>来源：wushixiongai.com 架构-注意力优化</p></blockquote><p><strong>问题背景</strong>：标准Attention的HBM访问复杂度为 O(N²)，GPU算力被内存带宽瓶颈严重制约。</p><p><strong>核心设计</strong>：</p><ol><li><p><strong>分块计算（Tiling）+ Kernel融合</strong></p><ul><li>将Q、K、V分割成小块（如64/128）</li><li>所有计算在GPU高速片上SRAM中完成（速度约为HBM的100倍）</li><li>避免实例化完整的 N×N 注意力矩阵，HBM读写量从 O(N²) 降至 O(N)</li></ul></li><li><p><strong>Online Softmax（安全融合）</strong></p><ul><li>维护当前最大值 mᵢ，处理新块时增量更新</li><li>通过缩放因子 e^(m_old - m_new) 调整之前的指数项</li><li>增量更新归一化分母，保证数值稳定性</li></ul></li></ol><p><strong>训练 vs 推理价值</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">核心收益</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>训练</strong></td><td style="text-align:left;">显存从 O(N²)→O(N)，配合重计算策略，支持训练更长序列</td></tr><tr><td style="text-align:left;"><strong>推理</strong></td><td style="text-align:left;">配合KV Cache减少HBM访问瓶颈，Prefill阶段收益显著</td></tr></tbody></table><p><strong>版本演进</strong>：v1证明可行性 → v2优化非矩阵乘法 → v3为Hopper架构(H100)优化</p><h3 id="_3-3-ppo-vs-dpo-vs-grpo-对比" tabindex="-1">3.3 PPO vs DPO vs GRPO 对比 <a class="header-anchor" href="#_3-3-ppo-vs-dpo-vs-grpo-对比" aria-label="Permalink to &quot;3.3 PPO vs DPO vs GRPO 对比&quot;">​</a></h3><blockquote><p>来源：wushixiongai.com 强化学习-算法对比</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">对比维度</th><th style="text-align:left;">PPO（近端策略优化）</th><th style="text-align:left;">DPO（直接偏好优化）</th><th style="text-align:left;">GRPO（广义无奖励策略优化）</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>核心模型数量</strong></td><td style="text-align:left;">4个(Actor, Critic, RM, Ref)</td><td style="text-align:left;">2个(策略模型, 参考模型)</td><td style="text-align:left;">2个或1个</td></tr><tr><td style="text-align:left;"><strong>是否需要RM</strong></td><td style="text-align:left;">是</td><td style="text-align:left;">否</td><td style="text-align:left;">否</td></tr><tr><td style="text-align:left;"><strong>是否需要Critic</strong></td><td style="text-align:left;">是</td><td style="text-align:left;">否</td><td style="text-align:left;">否</td></tr><tr><td style="text-align:left;"><strong>核心思想</strong></td><td style="text-align:left;">裁剪目标函数限制更新幅度</td><td style="text-align:left;">跳过RM，直接用偏好数据优化策略</td><td style="text-align:left;">组内相对奖励估计优势</td></tr><tr><td style="text-align:left;"><strong>训练稳定性</strong></td><td style="text-align:left;">稳定但需精细调参</td><td style="text-align:left;">好</td><td style="text-align:left;">依赖奖励规则质量</td></tr><tr><td style="text-align:left;"><strong>适用场景</strong></td><td style="text-align:left;">通用复杂对齐任务</td><td style="text-align:left;">快速迭代、简单偏好</td><td style="text-align:left;">数学/代码等可验证任务</td></tr><tr><td style="text-align:left;"><strong>代表模型</strong></td><td style="text-align:left;">ChatGPT(InstructGPT)</td><td style="text-align:left;">Llama系列对齐</td><td style="text-align:left;">DeepSeek-R1</td></tr></tbody></table><p><strong>选型建议</strong>：</p><ul><li>通用聊天对齐 → PPO或DPO</li><li>数学/代码推理 → GRPO</li><li>快速原型 → DPO</li><li>工业界常用两阶段：DPO快速对齐 + PPO精细调优</li></ul><h3 id="_3-4-dpo-vs-ppo-深度对比" tabindex="-1">3.4 DPO vs PPO 深度对比 <a class="header-anchor" href="#_3-4-dpo-vs-ppo-深度对比" aria-label="Permalink to &quot;3.4 DPO vs PPO 深度对比&quot;">​</a></h3><blockquote><p>来源：wushixiongai.com 强化学习-对齐方法</p></blockquote><p><strong>核心区别</strong>：优化范式根本不同</p><ul><li><strong>PPO</strong>：在线强化学习，三模型架构，&quot;探索→反馈→更新&quot;循环</li><li><strong>DPO</strong>：离线监督学习，单模型架构，将RL问题转化为分类问题</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">PPO</th><th style="text-align:left;">DPO</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>算法原理</strong></td><td style="text-align:left;">在线RL，与RM交互优化策略</td><td style="text-align:left;">离线分类，直接最大化chosen/rejected似然比</td></tr><tr><td style="text-align:left;"><strong>实现复杂度</strong></td><td style="text-align:left;">高，需维护多个模型</td><td style="text-align:left;">低，几行代码即可实现</td></tr><tr><td style="text-align:left;"><strong>训练稳定性</strong></td><td style="text-align:left;">差，易出现reward hacking和模式崩溃</td><td style="text-align:left;">好，凸优化问题</td></tr><tr><td style="text-align:left;"><strong>效果上限</strong></td><td style="text-align:left;">高，在线探索能力强</td><td style="text-align:left;">中，对分布外数据敏感</td></tr><tr><td style="text-align:left;"><strong>数据需求</strong></td><td style="text-align:left;">中等（需RM打分）</td><td style="text-align:left;">需成对偏好数据</td></tr></tbody></table><p><strong>DPO局限</strong>：效果依赖BT模型假设，分布外泛化弱，长文本生成信号衰减严重。<br><strong>PPO不可替代场景</strong>：强探索任务（数学推理/代码生成）、长文本生成、多轮交互。</p><h3 id="_3-5-大模型优化方法全景" tabindex="-1">3.5 大模型优化方法全景 <a class="header-anchor" href="#_3-5-大模型优化方法全景" aria-label="Permalink to &quot;3.5 大模型优化方法全景&quot;">​</a></h3><blockquote><p>来源：wushixiongai.com 基础设施-模型优化</p></blockquote><p><strong>三大阶段优化策略</strong>：</p><h4 id="训练阶段" tabindex="-1">训练阶段 <a class="header-anchor" href="#训练阶段" aria-label="Permalink to &quot;训练阶段&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">优化方向</th><th style="text-align:left;">方法</th><th style="text-align:left;">效果</th></tr></thead><tbody><tr><td style="text-align:left;">并行策略</td><td style="text-align:left;">数据并行(DDP/FSDP)、模型并行(Tensor/Pipeline)、ZeRO优化</td><td style="text-align:left;">突破单卡显存限制</td></tr><tr><td style="text-align:left;">计算效率</td><td style="text-align:left;">混合精度(FP16/BF16，提速2-3倍)、梯度检查点(节省40-60%显存)、Flash Attention(提速2-4倍)</td><td style="text-align:left;">显著提升训练速度</td></tr></tbody></table><h4 id="推理阶段" tabindex="-1">推理阶段 <a class="header-anchor" href="#推理阶段" aria-label="Permalink to &quot;推理阶段&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">优化方向</th><th style="text-align:left;">方法</th><th style="text-align:left;">效果</th></tr></thead><tbody><tr><td style="text-align:left;">内存优化</td><td style="text-align:left;">KV Cache + PageAttention + MQA/GQA</td><td style="text-align:left;">降低长文本显存占用</td></tr><tr><td style="text-align:left;">计算优化</td><td style="text-align:left;">Continuous Batching</td><td style="text-align:left;">提升GPU利用率</td></tr><tr><td style="text-align:left;">解码优化</td><td style="text-align:left;">投机解码(Speculative Decoding，提速2-3倍)、并行化Top-K/Top-P</td><td style="text-align:left;">降低延迟</td></tr></tbody></table><h4 id="部署阶段" tabindex="-1">部署阶段 <a class="header-anchor" href="#部署阶段" aria-label="Permalink to &quot;部署阶段&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">优化方向</th><th style="text-align:left;">方法</th><th style="text-align:left;">精度损失</th></tr></thead><tbody><tr><td style="text-align:left;">量化</td><td style="text-align:left;">INT8(SmoothQuant)</td><td style="text-align:left;">&lt;1%</td></tr><tr><td style="text-align:left;">量化</td><td style="text-align:left;">INT4(GPTQ/AWQ)</td><td style="text-align:left;">2-5%</td></tr><tr><td style="text-align:left;">蒸馏</td><td style="text-align:left;">模型蒸馏</td><td style="text-align:left;">可控</td></tr><tr><td style="text-align:left;">服务层</td><td style="text-align:left;">模型切分部署(PP+TP)、请求调度(优先级队列/抢占式)</td><td style="text-align:left;">-</td></tr></tbody></table><p><strong>系统性优化思维</strong>：「全栈分析 → 定位瓶颈 → 针对性优化」</p><ul><li>瓶颈在通信与计算？→ 优化并行策略</li><li>瓶颈是内存带宽？→ 量化 + KV Cache优化</li><li>瓶颈是请求波动？→ 弹性扩缩容 + Continuous Batching</li></ul><h3 id="_3-6-推理框架对比" tabindex="-1">3.6 推理框架对比 <a class="header-anchor" href="#_3-6-推理框架对比" aria-label="Permalink to &quot;3.6 推理框架对比&quot;">​</a></h3><blockquote><p>来源：wushixiongai.com 基础设施-推理框架</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">vLLM</th><th style="text-align:left;">TensorRT-LLM</th><th style="text-align:left;">HuggingFace TGI</th><th style="text-align:left;">llama.cpp</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>核心创新</strong></td><td style="text-align:left;">PagedAttention</td><td style="text-align:left;">算子融合+TensorRT</td><td style="text-align:left;">开箱即用HuggingFace生态</td><td style="text-align:left;">CPU/GPU混合+极致量化</td></tr><tr><td style="text-align:left;"><strong>吞吐量</strong></td><td style="text-align:left;">⭐⭐⭐⭐⭐</td><td style="text-align:left;">⭐⭐⭐⭐⭐</td><td style="text-align:left;">⭐⭐⭐</td><td style="text-align:left;">⭐⭐</td></tr><tr><td style="text-align:left;"><strong>延迟(P99)</strong></td><td style="text-align:left;">低</td><td style="text-align:left;">极低</td><td style="text-align:left;">中等</td><td style="text-align:left;">高</td></tr><tr><td style="text-align:left;"><strong>易用性</strong></td><td style="text-align:left;">好</td><td style="text-align:left;">较差（需编译转换）</td><td style="text-align:left;">最好</td><td style="text-align:left;">好</td></tr><tr><td style="text-align:left;"><strong>模型支持</strong></td><td style="text-align:left;">广(HF生态)</td><td style="text-align:left;">需转ONNX/TensorRT</td><td style="text-align:left;">广(HF Hub)</td><td style="text-align:left;">Llama系列等</td></tr></tbody></table><p><strong>选型建议</strong>：</p><ul><li>高吞吐在线服务 → vLLM</li><li>极致延迟要求(P99&lt;50ms) → TensorRT-LLM</li><li>快速验证/多模型切换 → HuggingFace TGI</li><li>边缘设备/CPU部署 → llama.cpp</li></ul><h3 id="_3-7-react框架" tabindex="-1">3.7 ReAct框架 <a class="header-anchor" href="#_3-7-react框架" aria-label="Permalink to &quot;3.7 ReAct框架&quot;">​</a></h3><blockquote><p>来源：字节一面面试题</p></blockquote><p>ReAct = Reasoning + Acting，三个核心组件循环：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thought → Action → Observation → Thought → Action → Observation → ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th style="text-align:left;">组件</th><th style="text-align:left;">含义</th><th style="text-align:left;">作用</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Thought（思考）</strong></td><td style="text-align:left;">LLM分析当前状态，决定下一步做什么</td><td style="text-align:left;">推理与规划</td></tr><tr><td style="text-align:left;"><strong>Action（行动）</strong></td><td style="text-align:left;">执行具体操作（调用工具/API/搜索）</td><td style="text-align:left;">与环境交互</td></tr><tr><td style="text-align:left;"><strong>Observation（观察）</strong></td><td style="text-align:left;">获取行动结果作为反馈</td><td style="text-align:left;">更新状态，指导下一步</td></tr></tbody></table><p><strong>与传统LLM的区别</strong>：传统LLM一次性生成答案；ReAct Agent通过&quot;思考→行动→观察&quot;循环，逐步推理并利用外部工具完成任务，更可靠、可解释。</p><h3 id="_3-7-llm-vs-agent" tabindex="-1">3.7 LLM vs Agent <a class="header-anchor" href="#_3-7-llm-vs-agent" aria-label="Permalink to &quot;3.7 LLM vs Agent&quot;">​</a></h3><blockquote><p>来源：阿里一面面试题</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">LLM</th><th style="text-align:left;">Agent</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>核心能力</strong></td><td style="text-align:left;">文本生成</td><td style="text-align:left;">自主决策+执行</td></tr><tr><td style="text-align:left;"><strong>记忆</strong></td><td style="text-align:left;">仅上下文窗口</td><td style="text-align:left;">短期+长期记忆系统</td></tr><tr><td style="text-align:left;"><strong>工具使用</strong></td><td style="text-align:left;">无</td><td style="text-align:left;">可调用API/数据库/搜索等外部工具</td></tr><tr><td style="text-align:left;"><strong>规划</strong></td><td style="text-align:left;">无</td><td style="text-align:left;">可分解任务，制定多步计划</td></tr><tr><td style="text-align:left;"><strong>交互</strong></td><td style="text-align:left;">被动响应</td><td style="text-align:left;">主动执行、多轮交互</td></tr></tbody></table><p>Agent = LLM + 规划(Planning) + 记忆(Memory) + 工具使用(Tool Use) + 行动(Action)</p><h3 id="_3-8-agent工具调用-vs-普通函数调用" tabindex="-1">3.8 Agent工具调用 vs 普通函数调用 <a class="header-anchor" href="#_3-8-agent工具调用-vs-普通函数调用" aria-label="Permalink to &quot;3.8 Agent工具调用 vs 普通函数调用&quot;">​</a></h3><blockquote><p>来源：美团二面面试题</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">普通函数调用</th><th style="text-align:left;">Agent工具调用</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>调用方式</strong></td><td style="text-align:left;">代码显式调用</td><td style="text-align:left;">LLM自主决策何时调用</td></tr><tr><td style="text-align:left;"><strong>参数生成</strong></td><td style="text-align:left;">程序员硬编码</td><td style="text-align:left;">LLM根据上下文动态生成</td></tr><tr><td style="text-align:left;"><strong>结果处理</strong></td><td style="text-align:left;">固定逻辑</td><td style="text-align:left;">LLM解析结果并决定下一步</td></tr><tr><td style="text-align:left;"><strong>灵活性</strong></td><td style="text-align:left;">固定流程</td><td style="text-align:left;">动态适应不同场景</td></tr></tbody></table><p>核心差异：Agent的工具调用是<strong>语义驱动</strong>而非<strong>代码驱动</strong>，由LLM理解用户意图后自主决定调用哪个工具、传什么参数、如何利用结果。</p><h3 id="_3-9-rag幻觉定位与解决" tabindex="-1">3.9 RAG幻觉定位与解决 <a class="header-anchor" href="#_3-9-rag幻觉定位与解决" aria-label="Permalink to &quot;3.9 RAG幻觉定位与解决&quot;">​</a></h3><blockquote><p>来源：淘天三面面试题</p></blockquote><p><strong>系统定位方法</strong>：</p><ol><li><strong>检索问题</strong>：检索到的文档是否真正相关？→ 检查chunk策略、Embedding模型、检索算法</li><li><strong>Prompt问题</strong>：上下文是否被有效利用？→ 检查System Prompt是否要求基于上下文回答</li><li><strong>生成模型问题</strong>：模型是否倾向于忽略上下文？→ 检查模型能力、温度设置</li></ol><p><strong>解决策略</strong>：</p><ul><li>检索层面：优化chunk分隔、混合检索(向量+关键词)、Rerank重排序</li><li>Prompt层面：明确指令(&quot;仅基于提供的上下文回答&quot;)、结构化提示、引用要求</li><li>模型层面：选择更强指令遵循能力的模型</li></ul><h3 id="_3-10-rag-rerank-重排序" tabindex="-1">3.10 RAG Rerank（重排序） <a class="header-anchor" href="#_3-10-rag-rerank-重排序" aria-label="Permalink to &quot;3.10 RAG Rerank（重排序）&quot;">​</a></h3><blockquote><p>来源：京东面试官连环问</p></blockquote><p><strong>为什么需要Rerank</strong>：初步向量检索可能召回20条，其中15条不相关 → 需要二次精排</p><p><strong>Rerank模型选择</strong>：不直接用GPT-4的原因</p><ul><li><strong>成本</strong>：GPT-4调用费用高，不适合高频打分</li><li><strong>延迟</strong>：GPT-4推理慢，影响整体响应时间</li><li><strong>专用性</strong>：Cross-Encoder重排序模型(BGE-Reranker、Cohere Rerank)专为此任务优化</li></ul><p><strong>流程</strong>：检索(Top-K) → Rerank精排 → 取Top-N送入LLM生成</p><h3 id="_3-11-rag性能优化" tabindex="-1">3.11 RAG性能优化 <a class="header-anchor" href="#_3-11-rag性能优化" aria-label="Permalink to &quot;3.11 RAG性能优化&quot;">​</a></h3><blockquote><p>来源：京东二面面试题（首字响应5秒）</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">环节</th><th style="text-align:left;">优化策略</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>检索加速</strong></td><td style="text-align:left;">向量索引优化(HNSW参数调优)、结果缓存、并行检索</td></tr><tr><td style="text-align:left;"><strong>Rerank加速</strong></td><td style="text-align:left;">使用轻量Rerank模型、减少Rerank候选数</td></tr><tr><td style="text-align:left;"><strong>生成加速</strong></td><td style="text-align:left;">流式输出(streaming)、投机解码、量化推理</td></tr><tr><td style="text-align:left;"><strong>架构优化</strong></td><td style="text-align:left;">预取(prefetch)、异步流水线</td></tr></tbody></table><h3 id="_3-12-pdf-复杂文档解析" tabindex="-1">3.12 PDF/复杂文档解析 <a class="header-anchor" href="#_3-12-pdf-复杂文档解析" aria-label="Permalink to &quot;3.12 PDF/复杂文档解析&quot;">​</a></h3><blockquote><p>来源：阿里二面、字节二面面试题</p></blockquote><p><strong>难点</strong>：双栏排版、表格结构、图片内容、语义完整性破坏</p><p><strong>解析策略</strong>：</p><ol><li><strong>版面分析</strong>：先用版面检测模型识别文字/表格/图片区域</li><li><strong>分模块处理</strong>： <ul><li>纯文本 → 标准段落分块</li><li>表格 → 专用OCR + 结构化提取（保留行列关系）</li><li>图片 → 多模态模型理解或OCR提取文字</li></ul></li><li><strong>语义分块</strong>：按语义边界分块，而非固定长度切分</li><li><strong>元数据保留</strong>：保留页码、章节、标题层级等结构信息</li></ol><h3 id="_3-13-归一化层详解" tabindex="-1">3.13 归一化层详解 <a class="header-anchor" href="#_3-13-归一化层详解" aria-label="Permalink to &quot;3.13 归一化层详解&quot;">​</a></h3><blockquote><p>来源：wushixiongai.com 架构-归一化</p></blockquote><p><strong>为何Transformer用LayerNorm而非BatchNorm</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">BatchNorm</th><th style="text-align:left;">LayerNorm</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>归一化维度</strong></td><td style="text-align:left;">跨batch，同一特征维度</td><td style="text-align:left;">跨特征，同一样本内</td></tr><tr><td style="text-align:left;"><strong>batch_size依赖</strong></td><td style="text-align:left;">强依赖，小batch不稳定</td><td style="text-align:left;">不依赖</td></tr><tr><td style="text-align:left;"><strong>序列长度适应</strong></td><td style="text-align:left;">差</td><td style="text-align:left;">好，天然适配变长序列</td></tr><tr><td style="text-align:left;"><strong>训练/推理一致性</strong></td><td style="text-align:left;">需维护running mean/var</td><td style="text-align:left;">天然一致</td></tr></tbody></table><p><strong>LayerNorm vs RMSNorm</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">LayerNorm</th><th style="text-align:left;">RMSNorm</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>计算方式</strong></td><td style="text-align:left;">减均值+除标准差</td><td style="text-align:left;">仅除均方根(RMS)</td></tr><tr><td style="text-align:left;"><strong>计算量</strong></td><td style="text-align:left;">较高</td><td style="text-align:left;">减少约1/3（去掉均值计算）</td></tr><tr><td style="text-align:left;"><strong>训练速度</strong></td><td style="text-align:left;">较慢</td><td style="text-align:left;">快7-15%</td></tr><tr><td style="text-align:left;"><strong>主流选择</strong></td><td style="text-align:left;">BERT/GPT-2</td><td style="text-align:left;">LLaMA系列/PaLM</td></tr></tbody></table><p>LLaMA选择RMSNorm的原因：计算效率更高，在训练稳定性上表现不差，已成为新一代模型标配。</p><h3 id="_3-14-位置编码" tabindex="-1">3.14 位置编码 <a class="header-anchor" href="#_3-14-位置编码" aria-label="Permalink to &quot;3.14 位置编码&quot;">​</a></h3><blockquote><p>来源：wushixiongai.com 架构-位置编码</p></blockquote><p><strong>作用</strong>：Transformer的自注意力机制本身是<strong>置换不变的</strong>（permutation-invariant），位置编码为模型注入序列顺序信息，使其能够区分&quot;我爱你&quot;和&quot;你爱我&quot;。</p><p><strong>主要类型</strong>：</p><ul><li><strong>绝对位置编码</strong>：正弦/余弦(Sinusoidal)、可学习(Learned)</li><li><strong>相对位置编码</strong>：注意力计算中考虑token间相对距离</li><li><strong>旋转位置编码(RoPE)</strong>：通过旋转矩阵编码相对位置，LLaMA/GPT-NeoX采用</li></ul><h3 id="_3-15-pytorch动态计算图" tabindex="-1">3.15 PyTorch动态计算图 <a class="header-anchor" href="#_3-15-pytorch动态计算图" aria-label="Permalink to &quot;3.15 PyTorch动态计算图&quot;">​</a></h3><blockquote><p>来源：wushixiongai.com 训练-框架原理</p></blockquote><p><strong>核心机制</strong>：</p><ul><li><strong>Define-by-Run</strong>：每次前向传播构建新计算图，图结构随输入动态变化</li><li><strong>自动微分</strong>：反向传播时沿计算图自动计算梯度（链式法则）</li><li><strong>优势</strong>：灵活支持变长输入、条件分支、循环等动态结构</li></ul><h3 id="_3-16-agent长期记忆" tabindex="-1">3.16 Agent长期记忆 <a class="header-anchor" href="#_3-16-agent长期记忆" aria-label="Permalink to &quot;3.16 Agent长期记忆&quot;">​</a></h3><blockquote><p>来源：面试官追问</p></blockquote><p><strong>存储方案</strong>：</p><ul><li><strong>短期记忆</strong>：对话历史（上下文窗口内）</li><li><strong>长期记忆</strong>： <ul><li>向量数据库存储(如Milvus/Pinecone) → 语义检索</li><li>知识图谱 → 结构化关系</li><li>用户画像/偏好存储 → 个性化</li></ul></li></ul><p><strong>检索策略</strong>：</p><ul><li>相似度检索（向量）</li><li>时间衰减（越近越重要）</li><li>混合检索（关键词+语义）</li></ul><h3 id="_3-17-llm面临的主要挑战" tabindex="-1">3.17 LLM面临的主要挑战 <a class="header-anchor" href="#_3-17-llm面临的主要挑战" aria-label="Permalink to &quot;3.17 LLM面临的主要挑战&quot;">​</a></h3><blockquote><p>来源：wushixiongai.com 综合-挑战</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">挑战</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>计算资源消耗</strong></td><td style="text-align:left;">训练/推理成本极高，千亿参数模型需要大量GPU</td></tr><tr><td style="text-align:left;"><strong>推理延迟</strong></td><td style="text-align:left;">自回归生成速度慢，影响实时应用</td></tr><tr><td style="text-align:left;"><strong>幻觉问题</strong></td><td style="text-align:left;">生成看似合理但事实错误的内容</td></tr><tr><td style="text-align:left;"><strong>上下文长度限制</strong></td><td style="text-align:left;">长文本处理能力受限（虽有改进但仍存在）</td></tr><tr><td style="text-align:left;"><strong>可控性与安全性</strong></td><td style="text-align:left;">难以完全控制输出，存在安全风险</td></tr><tr><td style="text-align:left;"><strong>评估困难</strong></td><td style="text-align:left;">开放式生成质量难以自动化评估</td></tr></tbody></table><hr><h2 id="四、项目案例" tabindex="-1">四、项目案例 <a class="header-anchor" href="#四、项目案例" aria-label="Permalink to &quot;四、项目案例&quot;">​</a></h2><p>公众号背后的训练营体系沉淀了多个实战项目：</p><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">核心技术点</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>企业培训问答Agent</strong></td><td style="text-align:left;">多轮追问、上下文记忆、身份指令控制</td></tr><tr><td style="text-align:left;"><strong>金融研报RAG系统</strong></td><td style="text-align:left;">混合检索、Cross-Encoder重排序、多模态文档解析</td></tr><tr><td style="text-align:left;"><strong>行业深研助手DeepResearch</strong></td><td style="text-align:left;">查询→检索→筛选→总结→整理→入库全链路</td></tr><tr><td style="text-align:left;"><strong>深学AI学习助手</strong></td><td style="text-align:left;">思维链路建模、输出可解释性</td></tr></tbody></table><hr><h2 id="五、资源链接" tabindex="-1">五、资源链接 <a class="header-anchor" href="#五、资源链接" aria-label="Permalink to &quot;五、资源链接&quot;">​</a></h2><ul><li>面试题库：<a href="https://www.wushixiongai.com/" target="_blank" rel="noreferrer">https://www.wushixiongai.com/</a> （840道真题）</li><li>题库页面：<a href="https://www.wushixiongai.com/questions/" target="_blank" rel="noreferrer">https://www.wushixiongai.com/questions/</a></li><li>项目案例库：<a href="https://www.wushixiongai.com/projects" target="_blank" rel="noreferrer">https://www.wushixiongai.com/projects</a></li><li>训练营：<a href="https://www.wsxdmx.com/camp/" target="_blank" rel="noreferrer">https://www.wsxdmx.com/camp/</a></li><li>知乎专栏：<a href="https://www.zhihu.com/column/c_1039097450233057280" target="_blank" rel="noreferrer">https://www.zhihu.com/column/c_1039097450233057280</a></li><li>历史文章索引：<a href="https://www.jintiankansha.com/column/AWf4PdmuQ7" target="_blank" rel="noreferrer">https://www.jintiankansha.com/column/AWf4PdmuQ7</a></li></ul><hr><blockquote><p><strong>说明</strong>：以上内容基于公开来源搜集整理。由于微信公众号文章无法通过API直接抓取全文，部分文章仅收录了标题和核心问题摘要。面试题库中有840道题，本文收录了已公开的约40道面试题及其中24道的详细解答。如需完整题库和各题的详细书面答案+口语版讲法+概念图解，请访问官方网站 wushixiongai.com。</p></blockquote>',132)])])}const h=e(d,[["render",r]]);export{y as __pageData,h as default};
